import{_ as e,o as r,c as a,ai as o}from"./chunks/framework.C33Uq6m-.js";const i="/llmxray/docs/educators/temperature-distribution.svg",s="/llmxray/docs/educators/temperature-cliff.svg",n="/llmxray/docs/educators/sampling-methods.svg",b=JSON.parse('{"title":"Module 2: How Does Temperature Work?","description":"","frontmatter":{},"headers":[],"relativePath":"en/community/educators/module-2.md","filePath":"en/community/educators/module-2.md"}'),l={name:"en/community/educators/module-2.md"};function d(h,t,p,u,c,m){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="module-2-how-does-temperature-work" tabindex="-1">Module 2: How Does Temperature Work? <a class="header-anchor" href="#module-2-how-does-temperature-work" aria-label="Permalink to &quot;Module 2: How Does Temperature Work?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>The Experimenter</strong> — Find the phase transition</p><p><strong>Duration:</strong> 60 min | <strong>Difficulty:</strong> Beginner | <strong>Prerequisite:</strong> <a href="./module-1.html">Module 1</a></p></div><h2 id="the-aha-moment" tabindex="-1">The Aha Moment <a class="header-anchor" href="#the-aha-moment" aria-label="Permalink to &quot;The Aha Moment&quot;">​</a></h2><blockquote><p>Temperature isn&#39;t a creativity dial — it&#39;s a probability redistribution. And it doesn&#39;t degrade gradually. There&#39;s a cliff.</p></blockquote><p>Students discover that temperature controls a mathematical transformation of the probability distribution over the vocabulary. Small changes near the cliff produce dramatic quality shifts — a phase transition, not a linear scale.</p><p><img src="'+i+'" alt="How Temperature Reshapes the Probability Distribution"></p><hr><h2 id="conceptual-background" tabindex="-1">Conceptual Background <a class="header-anchor" href="#conceptual-background" aria-label="Permalink to &quot;Conceptual Background&quot;">​</a></h2><h3 id="what-temperature-actually-does" tabindex="-1">What temperature actually does <a class="header-anchor" href="#what-temperature-actually-does" aria-label="Permalink to &quot;What temperature actually does&quot;">​</a></h3><p>After the model computes a score (logit) for every token in the vocabulary, these scores are passed through a <strong>softmax function</strong> to produce probabilities. Temperature modifies this softmax:</p><p><strong>Standard softmax:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(token_i) = exp(z_i) / sum_j exp(z_j)</span></span></code></pre></div><p><strong>Softmax with temperature T:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(token_i) = exp(z_i / T) / sum_j exp(z_j / T)</span></span></code></pre></div><p>The effect:</p><ul><li><strong>T &lt; 1</strong> — Divides logits by a number less than 1, making large logits even larger relative to small ones. The distribution becomes <strong>sharper</strong> (more peaked). The top token dominates.</li><li><strong>T = 1</strong> — No modification. The distribution is as the model computed it.</li><li><strong>T &gt; 1</strong> — Divides logits by a number greater than 1, compressing all logits toward zero. The distribution becomes <strong>flatter</strong> (more uniform). All tokens become roughly equally likely.</li><li><strong>T → 0</strong> — The distribution collapses to a single point. Only the highest-logit token has non-zero probability. This is <strong>greedy decoding</strong>.</li></ul><h3 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h3><p>Temperature is the most commonly adjusted parameter when using LLMs, but it&#39;s widely misunderstood. People describe it as &quot;creativity vs accuracy&quot; — but that&#39;s a simplification. What it actually controls is the <strong>entropy of the sampling distribution</strong>.</p><p>Low entropy = predictable, repetitive output. High entropy = diverse, surprising, but potentially nonsensical output. The right setting depends entirely on the task.</p><h3 id="the-phase-transition" tabindex="-1">The phase transition <a class="header-anchor" href="#the-phase-transition" aria-label="Permalink to &quot;The phase transition&quot;">​</a></h3><p>Unlike a volume dial that smoothly goes from quiet to loud, temperature exhibits a <strong>phase transition</strong>. Output quality stays high across a wide range (T=0 to T≈0.8-1.0), then drops off sharply in a narrow band. This is because:</p><ol><li>At low temperatures, the top token has such high probability that sampling is nearly deterministic regardless</li><li>At moderate temperatures, the top 3-5 tokens share most of the probability — still reasonable choices</li><li>At a critical point, enough probability leaks to implausible tokens that the model starts generating incoherent text</li><li>Beyond the cliff, output becomes essentially random</li></ol><p><img src="'+s+'" alt="The Temperature Cliff"></p><h3 id="other-sampling-methods" tabindex="-1">Other sampling methods <a class="header-anchor" href="#other-sampling-methods" aria-label="Permalink to &quot;Other sampling methods&quot;">​</a></h3><p>Temperature is not the only way to control token selection. Modern LLMs support several sampling strategies that can be combined:</p><p><img src="'+n+'" alt="Sampling Methods Compared"></p><table tabindex="0"><thead><tr><th>Method</th><th>What it does</th><th>When to use</th></tr></thead><tbody><tr><td><strong>Greedy (T=0)</strong></td><td>Always picks the highest-probability token</td><td>Factual answers, deterministic output</td></tr><tr><td><strong>Temperature</strong></td><td>Reshapes the probability distribution</td><td>General-purpose control of output variety</td></tr><tr><td><strong>Top-k</strong></td><td>Samples from only the k highest-probability tokens</td><td>Simple diversity control, fixed candidate set</td></tr><tr><td><strong>Top-p (nucleus)</strong></td><td>Samples from the smallest set of tokens whose cumulative probability exceeds p</td><td>Adaptive diversity — more options when uncertain, fewer when confident</td></tr><tr><td><strong>Min-p</strong></td><td>Removes tokens with probability below a fraction of the top token</td><td>Newer alternative to top-p, more intuitive threshold</td></tr><tr><td><strong>Mirostat</strong></td><td>Dynamically adjusts sampling to maintain a target perplexity</td><td>Consistent &quot;surprise level&quot; regardless of context</td></tr><tr><td><strong>Repetition penalty</strong></td><td>Reduces probability of recently generated tokens</td><td>Prevents loops and repetitive text</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">These methods compose</p><p>In practice, multiple methods are applied in sequence: temperature first (reshapes distribution), then top-k or top-p (truncates the distribution), then sampling from what remains. LLMxRay&#39;s Compare feature lets you test different combinations side by side.</p></div><hr><h2 id="hands-on-exercises" tabindex="-1">Hands-On Exercises <a class="header-anchor" href="#hands-on-exercises" aria-label="Permalink to &quot;Hands-On Exercises&quot;">​</a></h2><h3 id="exercise-1-the-temperature-sweep" tabindex="-1">Exercise 1: The temperature sweep <a class="header-anchor" href="#exercise-1-the-temperature-sweep" aria-label="Permalink to &quot;Exercise 1: The temperature sweep&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Open <strong>Compare</strong> in LLMxRay</li><li>Click <strong>Temperature Sweep</strong> preset — this creates 3 slots with temperatures 0.2, 0.7, and 1.2</li><li>Add a 4th slot manually and set it to 2.0</li><li>Use this prompt: <em>&quot;Write a function in Python to check if a number is prime&quot;</em></li><li>Click <strong>Run All</strong> and watch all 4 generate simultaneously</li><li>Compare the results in <strong>Grid View</strong></li></ol><p><strong>What to observe:</strong></p><ul><li><strong>T=0.2</strong>: Clean, standard implementation. Almost identical if you run it again.</li><li><strong>T=0.7</strong>: Slight variations in variable names or comments. Still correct.</li><li><strong>T=1.2</strong>: More creative approaches (maybe a different algorithm), but watch for subtle bugs.</li><li><strong>T=2.0</strong>: Variable names become strange, logic errors appear, possibly incomplete.</li></ul><p>Switch to <strong>Diff View</strong> to see exactly which words changed between the outputs.</p><p><strong>Key question:</strong> Between which two temperatures does the quality drop feel sharpest?</p><hr><h3 id="exercise-2-finding-the-cliff" tabindex="-1">Exercise 2: Finding the cliff <a class="header-anchor" href="#exercise-2-finding-the-cliff" aria-label="Permalink to &quot;Exercise 2: Finding the cliff&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Stay in <strong>Compare</strong>. Set up 4 slots with temperatures: 0.7, 0.9, 1.1, 1.3</li><li>Prompt: <em>&quot;Write a function in Python to check if a number is prime&quot;</em></li><li>Run 3 times. For each run, mark whether each slot produced correct code (Yes/No)</li><li>Record your results in a table:</li></ol><table tabindex="0"><thead><tr><th>Temperature</th><th>Run 1</th><th>Run 2</th><th>Run 3</th><th>Correct rate</th></tr></thead><tbody><tr><td>0.7</td><td></td><td></td><td></td><td>/3</td></tr><tr><td>0.9</td><td></td><td></td><td></td><td>/3</td></tr><tr><td>1.1</td><td></td><td></td><td></td><td>/3</td></tr><tr><td>1.3</td><td></td><td></td><td></td><td>/3</td></tr></tbody></table><ol start="5"><li>The cliff is where the correct rate drops sharply — usually between T=0.9 and T=1.2</li></ol><p><strong>Why this matters:</strong></p><p>This demonstrates that temperature isn&#39;t a linear trade-off. There&#39;s a <strong>narrow band</strong> where output goes from &quot;almost always correct&quot; to &quot;usually wrong.&quot; Finding this cliff for your specific model and task is one of the most practical skills in prompt engineering.</p><hr><h3 id="exercise-3-temperature-vs-task-type" tabindex="-1">Exercise 3: Temperature vs task type <a class="header-anchor" href="#exercise-3-temperature-vs-task-type" aria-label="Permalink to &quot;Exercise 3: Temperature vs task type&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>Set up 2 slots: both using the same model, one at T=0.2, the other at T=1.0</li><li><strong>Factual prompt:</strong> <em>&quot;What is the capital of France?&quot;</em><ul><li>Run it. Both should say &quot;Paris.&quot; Low temperature adds nothing here.</li></ul></li><li><strong>Creative prompt:</strong> <em>&quot;Write a haiku about debugging code at midnight&quot;</em><ul><li>Run it 3 times. Compare the variety.</li><li>At T=0.2, you&#39;ll get nearly the same haiku every time.</li><li>At T=1.0, you&#39;ll get genuinely different creative expressions.</li></ul></li><li><strong>Reasoning prompt:</strong> <em>&quot;A farmer has 15 sheep. All but 8 run away. How many sheep does the farmer have left?&quot;</em><ul><li>This is a trick question (answer: 8, not 7). Test at both temperatures.</li><li>Does temperature affect reasoning accuracy?</li></ul></li></ol><p><strong>Discussion:</strong> Why is there no single &quot;best&quot; temperature? What temperature would you choose for:</p><ul><li>A customer support chatbot?</li><li>A creative writing assistant?</li><li>A code completion tool?</li><li>A medical information system?</li></ul><hr><h3 id="exercise-4-determinism-and-seeds" tabindex="-1">Exercise 4: Determinism and seeds <a class="header-anchor" href="#exercise-4-determinism-and-seeds" aria-label="Permalink to &quot;Exercise 4: Determinism and seeds&quot;">​</a></h3><p><strong>What to do:</strong></p><ol><li>In <strong>Compare</strong>, use the <strong>Deterministic Pair</strong> preset — two slots with the same model, same settings, same seed, T=0</li><li>Run the same prompt 3 times</li><li>All outputs should be <strong>identical</strong> — the seed makes the random number generator reproducible</li><li>Now change one slot to T=0.7 (keep the same seed)</li><li>Run again 3 times — outputs will now differ between runs</li></ol><p><strong>What this reveals:</strong></p><ul><li>At T=0 (greedy), the seed doesn&#39;t matter — there&#39;s no randomness to control</li><li>At T&gt;0, the seed controls which random path is taken through the distribution</li><li>Same seed + same temperature = reproducible &quot;randomness&quot;</li><li>This is how researchers ensure experiment reproducibility while still using stochastic decoding</li></ul><div class="tip custom-block"><p class="custom-block-title">Why reproducibility matters</p><p>In research and production, you need to reproduce specific outputs for debugging, comparison, and audit. Setting a fixed seed with a moderate temperature gives you <strong>controlled variety</strong> — different from greedy (always the same) but reproducible when needed.</p></div><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>Temperature is a mathematical operation</strong> — it divides logits by T before softmax, reshaping the probability distribution</li><li><strong>The cliff is real</strong> — quality doesn&#39;t degrade linearly; there&#39;s a sharp transition where output goes from reliable to chaotic</li><li><strong>There&#39;s no universal best temperature</strong> — the optimal value depends on the task (factual, creative, reasoning)</li><li><strong>Temperature composes with other methods</strong> — top-k, top-p, and repetition penalty work alongside temperature</li><li><strong>Seeds enable reproducibility</strong> — fixed seed + fixed temperature = same output every time</li></ol><hr><h2 id="discussion-questions" tabindex="-1">Discussion Questions <a class="header-anchor" href="#discussion-questions" aria-label="Permalink to &quot;Discussion Questions&quot;">​</a></h2><ol><li>If a company deploys a chatbot at T=0 for safety, what do they lose? Is deterministic output always &quot;safer&quot;?</li><li>The cliff position varies by model. Why might a 70B model have a higher cliff temperature than a 3B model?</li><li>Creative writing assistants often use T=0.8-1.0. But whose creativity is it — the user&#39;s or the model&#39;s? Does temperature change this?</li><li>If you could only adjust one parameter (temperature, top-k, or top-p), which would you choose and why?</li></ol><hr><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><h3 id="academic-papers" tabindex="-1">Academic Papers <a class="header-anchor" href="#academic-papers" aria-label="Permalink to &quot;Academic Papers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paper</th><th>Authors</th><th>Year</th><th>Link</th></tr></thead><tbody><tr><td>Distilling the Knowledge in a Neural Network</td><td>Hinton, Vinyals, Dean</td><td>2015</td><td><a href="https://arxiv.org/abs/1503.02531" target="_blank" rel="noreferrer">arXiv:1503.02531</a></td></tr><tr><td>The Curious Case of Neural Text Degeneration</td><td>Holtzman, Buys, Du, Forbes, Choi</td><td>2019</td><td><a href="https://arxiv.org/abs/1904.09751" target="_blank" rel="noreferrer">arXiv:1904.09751</a></td></tr><tr><td>Hierarchical Neural Story Generation</td><td>Fan, Lewis, Dauphin</td><td>2018</td><td><a href="https://arxiv.org/abs/1805.04833" target="_blank" rel="noreferrer">arXiv:1805.04833</a></td></tr><tr><td>Mirostat: A Neural Text Decoding Algorithm</td><td>Basu, Ramachandran, Keskar, Varshney</td><td>2020</td><td><a href="https://arxiv.org/abs/2007.14966" target="_blank" rel="noreferrer">arXiv:2007.14966</a></td></tr><tr><td>Phase Transitions in the Output Distribution of LLMs</td><td>—</td><td>2024</td><td><a href="https://arxiv.org/abs/2405.17088" target="_blank" rel="noreferrer">arXiv:2405.17088</a></td></tr><tr><td>Turning Up the Heat: Min-p Sampling</td><td>—</td><td>2024</td><td><a href="https://arxiv.org/abs/2407.01082" target="_blank" rel="noreferrer">arXiv:2407.01082</a></td></tr><tr><td>The Effect of Sampling Temperature on Problem Solving in LLMs</td><td>Renze, Guven</td><td>2024</td><td><a href="https://arxiv.org/abs/2402.05201" target="_blank" rel="noreferrer">arXiv:2402.05201</a></td></tr><tr><td>CTRL: Conditional Transformer for Controllable Generation</td><td>Keskar, McCann, Varshney, Xiong, Socher</td><td>2019</td><td><a href="https://arxiv.org/abs/1909.05858" target="_blank" rel="noreferrer">arXiv:1909.05858</a></td></tr></tbody></table><h3 id="tutorials-and-explanations" tabindex="-1">Tutorials and Explanations <a class="header-anchor" href="#tutorials-and-explanations" aria-label="Permalink to &quot;Tutorials and Explanations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Author</th><th>Link</th></tr></thead><tbody><tr><td>The Unreasonable Effectiveness of Recurrent Neural Networks</td><td>Andrej Karpathy</td><td><a href="http://karpathy.github.io/2015/05/21/rnn-effectiveness/" target="_blank" rel="noreferrer">karpathy.github.io</a></td></tr><tr><td>Generation Configurations: Temperature, Top-k, Top-p</td><td>Chip Huyen</td><td><a href="https://huyenchip.com/2024/01/16/sampling.html" target="_blank" rel="noreferrer">huyenchip.com</a></td></tr><tr><td>Controllable Neural Text Generation</td><td>Lilian Weng</td><td><a href="https://lilianweng.github.io/posts/2021-01-02-controllable-text-generation/" target="_blank" rel="noreferrer">lilianweng.github.io</a></td></tr><tr><td>Sampling Parameters Explained: Intuition to Math</td><td>Let&#39;s Data Science</td><td><a href="https://letsdatascience.com/blog/llm-sampling-temperature-top-k-top-p-and-min-p-explained" target="_blank" rel="noreferrer">letsdatascience.com</a></td></tr><tr><td>Decoding Strategies in Large Language Models</td><td>mlabonne (HuggingFace)</td><td><a href="https://huggingface.co/blog/mlabonne/decoding-strategies" target="_blank" rel="noreferrer">huggingface.co/blog</a></td></tr></tbody></table><h3 id="interactive-tools" tabindex="-1">Interactive Tools <a class="header-anchor" href="#interactive-tools" aria-label="Permalink to &quot;Interactive Tools&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Link</th><th>What it does</th></tr></thead><tbody><tr><td>Transformer Explainer</td><td><a href="https://poloclub.github.io/transformer-explainer/" target="_blank" rel="noreferrer">poloclub.github.io</a></td><td>Full transformer visualization with live temperature slider</td></tr><tr><td>LLM Sampling Visualizer</td><td><a href="https://louis-7.github.io/llm-sampling-visualizer/" target="_blank" rel="noreferrer">louis-7.github.io</a></td><td>Adjust temperature, top-k, top-p and see distributions change</td></tr><tr><td>Temperature &amp; Top-k Visualizer</td><td><a href="https://andreban.github.io/temperature-topk-visualizer/" target="_blank" rel="noreferrer">andreban.github.io</a></td><td>Focused demo for temperature and top-k effects</td></tr></tbody></table><h3 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h3><p><strong>The origin of softmax temperature</strong> comes from Hinton et al. (2015), who introduced it for knowledge distillation — transferring knowledge from a large model to a small one by &quot;softening&quot; the probability distribution. The same parameter was later adopted for controlling text generation diversity.</p><p><strong>Nucleus sampling (top-p)</strong> was introduced by Holtzman et al. (2019) as a response to the observation that standard sampling with temperature produces either too-generic (low T) or too-random (high T) text. Their insight: instead of a fixed temperature, truncate the distribution to the smallest set of tokens covering a cumulative probability threshold. This adapts automatically — when the model is confident, fewer tokens are considered; when uncertain, more options remain.</p><p><strong>The phase transition is real, not a metaphor.</strong> Research by multiple teams (arXiv:2405.17088) using methods from statistical physics has shown that LLM output undergoes genuine phase transitions at specific temperature thresholds — with divergent statistical quantities at the transition points, just like phase transitions in physical systems.</p><p><strong>Mirostat</strong> (Basu et al., 2020) takes a different approach by targeting a specific perplexity level rather than a fixed distribution shape. It dynamically adjusts the sampling to maintain consistent &quot;surprise&quot; regardless of whether the model is generating a predictable phrase or navigating uncertain territory.</p><hr><h2 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h2><p><strong>Option A — Data collection (individual, 1 page):</strong> Run the cliff-finding experiment (Exercise 2) with 5 temperature values and 5 runs each. Present a table and line chart of correctness rate vs temperature. Identify the cliff point for your model.</p><p><strong>Option B — Comparative analysis (pairs, 1 page):</strong> Test the same prompt across 3 task types (factual, creative, reasoning) at 4 temperatures. For each combination, rate the output quality on a 1-5 scale. Present a heatmap and recommend optimal temperatures per task type.</p><p><strong>Option C — Technical explanation (individual, 500 words):</strong> Explain to a non-technical product manager why their chatbot should NOT use T=0, despite it being &quot;the safest option.&quot; Use specific examples from your experiments.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><p>In <strong><a href="./module-3.html">Module 3: Can AI Lie?</a></strong>, you&#39;ll use what you learned about probability distributions to understand <strong>confidence vs truth</strong>. A model can assign 95% probability to the wrong answer — and you&#39;ll discover why through benchmarks with real logprobs.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 2 of 8</strong> in the LLMxRay Educators Kit <a href="./module-1.html">← Module 1: What Is a Token?</a> | <a href="./index.html">Back to Curriculum</a> | <a href="./module-3.html">Module 3: Can AI Lie? →</a></p></div>',87)])])}const f=e(l,[["render",d]]);export{b as __pageData,f as default};
